    44→export const upgradeOrgAction = orgAction
    45→  .metadata({
    46→    permissions: {
    47→      subscription: ["manage"],
    48→    },
    49→  })
    50→  .schema(
    51→    z.object({
    52→      plan: z.string(),
    53→      annual: z.boolean().default(false),
    54→      successUrl: z.string(),
    55→      cancelUrl: z.string(),
    56→    }),
    57→  )
    58→  .action(
    59→    async ({
    60→      parsedInput: { plan, annual, successUrl, cancelUrl },
    61→      ctx: { org },
    62→    }) => {
    63→      if (!(await hasPermission({ subscription: ["manage"] }))) {
    64→        throw new ActionError(
    65→          "You do not have permission to manage subscriptions",
    66→        );
    67→      }
    68→
    69→      // Find the plan
    70→      const authPlan = AUTH_PLANS.find((p) => p.name === plan);
    71→      if (!authPlan) {
    72→        throw new ActionError(`Plan "${plan}" not found`);
    73→      }
    74→
    75→      // Get the price ID based on annual or monthly
    76→      const priceId = annual
    77→        ? authPlan.annualDiscountPriceId
    78→        : authPlan.priceId;
    79→      if (!priceId) {
    80→        throw new ActionError(`Price ID not found for plan "${plan}"`);
    81→      }
    82→
    83→      // Get or create Stripe customer
    84→      let customerId = org.stripeCustomerId;
    85→
    86→      if (!customerId) {
    87→        const customer = await stripe.customers.create({
    88→          email: org.email ?? undefined,
    89→          name: org.name,
    90→          metadata: {
    91→            organizationId: org.id,
    92→          },
    93→        });
    94→        customerId = customer.id;
    95→
    96→        // Update organization with the new customer ID
    97→        await prisma.organization.update({
    98→          where: { id: org.id },
    99→          data: { stripeCustomerId: customerId },
   100→        });
   101→      }
   102→
   103→      // Create checkout session
   104→      const session = await stripe.checkout.sessions.create({
   105→        customer: customerId,
   106→        payment_method_types: ["card"],
   107→        line_items: [
   108→          {
   109→            price: priceId,
   110→            quantity: 1,
   111→          },
   112→        ],
   113→        mode: "subscription",
   114→        success_url: `${getServerUrl()}${successUrl}?session_id={CHECKOUT_SESSION_ID}`,
   115→        cancel_url: `${getServerUrl()}${cancelUrl}`,
   116→        metadata: {
   117→          organizationId: org.id,
   118→          plan: plan,
   119→        },
   120→        subscription_data: {
   121→          metadata: {
   122→            organizationId: org.id,
   123→            plan: plan,
   124→          },
   125→        },
   126→      });
   127→
   128→      if (!session.url) {
   129→        throw new ActionError("Failed to create checkout session");
   130→      }
   131→
   132→      return {
   133→        url: session.url,
   134→      };
   135→    },
   136→  );
