   139→  .metadata({
   140→    permissions: {
   141→      subscription: ["manage"],
   142→    },
   143→  })
   144→  .schema(
   145→    z.object({
   146→      returnUrl: z.string(),
   147→    }),
   148→  )
   149→  .action(async ({ parsedInput: { returnUrl }, ctx: { org } }) => {
   150→    if (!(await hasPermission({ subscription: ["manage"] }))) {
   151→      throw new ActionError(
   152→        "You do not have permission to manage subscriptions",
   153→      );
   154→    }
   155→
   156→    const stripeCustomerId = org.stripeCustomerId;
   157→
   158→    if (!stripeCustomerId) {
   159→      throw new ActionError("No stripe customer id found");
   160→    }
   161→
   162→    // Get the current subscription
   163→    const subscription = await prisma.subscription.findFirst({
