   166→
   167→    if (!subscription?.stripeSubscriptionId) {
   168→      throw new ActionError("No active subscription found");
   169→    }
   170→
   171→    // Create billing portal session which allows the user to cancel
   172→    const stripeBilling = await stripe.billingPortal.sessions.create({
   173→      customer: stripeCustomerId,
   174→      return_url: `${getServerUrl()}${returnUrl}`,
   175→    });
   176→
   177→    if (!stripeBilling.url) {
   178→      throw new ActionError("Failed to create stripe billing portal session");
   179→    }
   180→
   181→    return {
   182→      url: stripeBilling.url,
   183→    };
