import { getMiddlewareUser, getRedirectUrl } from "@/lib/auth/middleware-utils";
import { SiteConfig } from "@/site-config";
import { getSessionCookie } from "better-auth/cookies";
import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

export async function middleware(request: NextRequest) {
  const { pathname } = request.nextUrl;

  // Redirect homepage based on account type
  if (pathname === "/") {
    const session = getSessionCookie(request, {
      cookiePrefix: SiteConfig.appId,
    });

    if (session) {
      const user = await getMiddlewareUser(request);
      if (user) {
        const url = new URL(request.url);
        url.pathname = getRedirectUrl(user.accountType);
        return NextResponse.redirect(url.toString());
      }
    }
  }

  // B2C routes protection - redirect professionals to /orgs
  if (
    pathname.startsWith("/dashboard") ||
    pathname.startsWith("/favorites") ||
    pathname.startsWith("/comparisons") ||
    pathname.startsWith("/alerts")
  ) {
    const user = await getMiddlewareUser(request);
    if (user?.accountType === "professional") {
      const url = new URL(request.url);
      url.pathname = "/orgs";
      return NextResponse.redirect(url.toString());
    }
  }

  // B2B routes protection - redirect individuals to /dashboard
  if (pathname.startsWith("/orgs")) {
    const user = await getMiddlewareUser(request);
    if (user?.accountType === "individual") {
      const url = new URL(request.url);
      url.pathname = "/dashboard";
      return NextResponse.redirect(url.toString());
    }
  }

  return NextResponse.next();
}

export const config = {
  matcher: [
    /*
     * Match all request paths except for the ones starting with:
     * - api (API routes)
     * - _next/static (static files)
     * - _next/image (image optimization files)
     * - favicon.ico, sitemap.xml, robots.txt (metadata files)
     */
    "/((?!api|_next/static|_next/image|favicon.ico|sitemap.xml|robots.txt).*)",
  ],
};
